    @PostMapping("/backup")
    public SystemTaskResponse createBackup(@RequestBody BackupRequestDTO requestDTO) {
        log.info("Creating backup to path: {}", requestDTO.getBackupPath());

        return backupService.createBackup(requestDTO);
    }

