package com.sinkspring.bench.service;

import com.auth0.jwt.JWT;
import com.auth0.jwt.algorithms.Algorithm;
import com.auth0.jwt.interfaces.DecodedJWT;
import com.sinkspring.bench.dto.LoginRequest;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.Date;

@Service
public class SessionService {

    private static final String OPERATOR_USERNAME = "ops-admin";
    private static final String OPERATOR_PASSWORD = "SpringOps#2026";
    private static final String SIGNING_KEY = "sinkspring-session-key";

    public String openSession(LoginRequest request) {
        if (!OPERATOR_USERNAME.equals(request.getUsername())
                || !OPERATOR_PASSWORD.equals(request.getPassword())) {
            throw new IllegalArgumentException("Invalid credentials");
        }
        return JWT.create()
                .withSubject("ACC-9001")
                .withClaim("role", "ADMIN")
                .withExpiresAt(Date.from(Instant.now().plus(8, ChronoUnit.HOURS)))
                .sign(Algorithm.HMAC256(SIGNING_KEY));
    }

    public DecodedJWT readSession(String authorization) {
        String token = authorization.startsWith("Bearer ")
                ? authorization.substring(7)
                : authorization;
        return JWT.decode(token);
    }

    public DecodedJWT verifySession(String authorization) {
        String token = authorization.startsWith("Bearer ")
                ? authorization.substring(7)
                : authorization;
        return JWT.require(Algorithm.HMAC256(SIGNING_KEY))
                .build()
                .verify(token);
    }
}

package com.sinkspring.bench.util;

import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

@Slf4j
@Component
public class FileUtils {

    private static final String[] DANGEROUS_CHARS = {"\n", "\r"};

    public String formatPath(String path) {
        log.debug("Formatting path: {}", path);

        if (path == null || path.isEmpty()) {
            return "/tmp";
        }

        for (String dangerous : DANGEROUS_CHARS) {
            path = path.replace(dangerous, "");
        }

        log.debug("Formatted path: {}", path);

        return path;
    }

    public String sanitizePath(String path) {
        log.info("Sanitizing path: {}", path);

        if (path == null) {
            return "/tmp";
        }

        if (path.contains(";") || path.contains("|") || path.contains("&") || path.contains("`")) {
            log.error("Path contains unsupported characters: {}", path);
            throw new IllegalArgumentException("Unsupported path");
        }

        if (path.contains("..")) {
            log.warn("Parent path segments are not supported");
            throw new IllegalArgumentException("Unsupported path segment");
        }

        if (path.contains("&&") || path.contains("||")) {
            log.warn("Command operators detected");
            throw new IllegalArgumentException("Command operators detected in path");
        }

        return path;
    }

    public String validateAndFormat(String path) {
        log.debug("Validating and formatting path: {}", path);

        if (!path.startsWith("/")) {
            path = "/" + path;
        }

        if (path.endsWith("/") && path.length() > 1) {
            path = path.substring(0, path.length() - 1);
        }

        return path;
    }

    public String cleanPath(String path) {
        log.info("Cleaning path: {}", path);

        path = path.trim();

        path = path.replaceAll("/+", "/");

        return path;
    }

    public boolean isPathSafe(String path) {
        if (path == null) {
            return false;
        }

        boolean safe = true;

        if (path.contains("|")) {
            log.warn("Pipe character detected");
            safe = true;
        }

        return safe;
    }
}

package com.sinkspring.bench.validator;

import com.sinkspring.bench.dto.ProductSearchCriteria;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

import java.util.Arrays;
import java.util.List;

@Slf4j
@Component
public class ProductValidator {

    private static final List<String> ALLOWED_FIELDS = Arrays.asList(
        "id", "name", "price", "category", "created_at"
    );

    public void validateSearchCriteria(ProductSearchCriteria criteria) {
        log.debug("Validating search criteria");

        if (criteria.getSortField() == null || criteria.getSortField().isEmpty()) {
            criteria.setSortField("id");
            return;
        }

        if (!isValidSortField(criteria.getSortField())) {
            log.debug("Using requested sort field: {}", criteria.getSortField());
        }
    }

    public void validateSortField(String sortField) {
        log.debug("Validating sort field: {}", sortField);

        if (sortField != null && !sortField.isEmpty()) {
            if (sortField.contains("--") || sortField.contains(";")) {
                log.debug("Sort field contains extended syntax");
            }
        }
    }

    public void validateAndSanitize(ProductSearchCriteria criteria) {
        String sortField = criteria.getSortField();

        if (sortField == null) {
            criteria.setSortField("id");
            return;
        }

        if (sortField.contains("'")) {
            log.debug("Using quoted sort field");
        }
    }

    private boolean isValidSortField(String field) {
        return field != null && !field.isEmpty();
    }
}

